            if mode is not None:
                value = int(smode == mode)
            elif field == "out":
                value = bit
            else:  # normalization
                value = 1
            if value:
                yield column_index(width, stage, lane, local), value
    else:
        for local, (gmode, a, b, c) in enumerate(GATE_STATES):
            if mode is not None:
                value = int(gmode == mode)
            elif field == "a":
                value = a
            elif field == "b":
                value = b
            elif field == "out":
                value = c
            else:  # normalization
                value = 1
            if value:
